'use strict';
const PLAYER_KEY='niti-player-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(16).slice(2);
const SPECIAL=[['S','Сила'],['P','Восприятие'],['E','Выносливость'],['C','Харизма'],['I','Интеллект'],['A','Ловкость'],['L','Удача']];
const initial=()=>({kind:'niti-player',version:1,profile:{name:'',concept:'',hp:'',defence:'',inventory:'',description:'',special:Object.fromEntries(SPECIAL.map(([k])=>[k,5]))},notes:[]});
function validPlayer(s){return !!s&&s.kind==='niti-player'&&s.version===1&&s.profile&&['name','concept','hp','defence','inventory','description'].every(k=>typeof s.profile[k]==='string'&&s.profile[k].length<=30000)&&s.profile.special&&SPECIAL.every(([k])=>Number.isInteger(s.profile.special[k])&&s.profile.special[k]>=1&&s.profile.special[k]<=10)&&Array.isArray(s.notes)&&s.notes.length<=1000&&s.notes.every(n=>n&&['id','title','text','date'].every(k=>typeof n[k]==='string')&&n.id.length>0&&n.id.length<120&&n.title.length<=200&&n.text.length<=30000&&Number.isFinite(Date.parse(n.date)))&&new Set(s.notes.map(n=>n.id)).size===s.notes.length;}
let player=initial(),storageOK=true;try{const raw=localStorage.getItem(PLAYER_KEY);if(raw){const data=JSON.parse(raw);if(validPlayer(data))player=data;}}catch{storageOK=false;}
let view=location.hash.slice(1)||'home',lastFocus=null;
const pages=[['home','На связи'],['character','Мой персонаж'],['notes','Мои заметки'],['dice','Кубики'],['help','Справка']];
function icon(key){const shapes={home:'<path d="m3 11 9-8 9 8v10h-6v-7H9v7H3Z"/>',character:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',notes:'<path d="M5 3h14v18H5zM9 7h6m-6 5h6m-6 5h3"/>',dice:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 0L7 15h10L12 2ZM3 7l14 8-5 7-5-7 14-8"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5m0 3v1"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[key]||shapes.home}</svg>`;}
function head(eyebrow,title,subtitle,actions=''){return `<div class="heading-row"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="subtitle">${subtitle}</p></div><div class="header-actions">${actions}</div></div>`;}
function btn(label,action,cls='',extra=''){return `<button type="button" class="button ${cls}" data-player-action="${action}" ${extra}>${label}</button>`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function save(){try{localStorage.setItem(PLAYER_KEY,JSON.stringify(player));storageOK=true;}catch{storageOK=false;}$('#saveStatus').textContent=storageOK?'● Личные записи сохранены':'! Не сохранено · скачай копию';return storageOK;}
function modifier(n){return n-5>=0?'+'+(n-5):String(n-5);}
function home(){const p=player.profile;return head('ЛИЧНОЕ ПРОСТРАНСТВО УЧАСТНИКА','Твоя история ещё впереди.','Персонаж, заметки и кубики. Всё под рукой во время игры.')+`<div class="player-home-grid"><section class="panel player-welcome"><div class="panel-header"><h2 class="panel-title">Терминал игрока</h2><span class="tag">OLYMPUS 2207</span></div><div class="player-vault"><img src="vault-art.svg" alt="Ретрофутуристический терминал рядом с гермодверью"></div><div class="player-welcome-body"><div class="player-kicker">ГОТОВ К СЛЕДУЮЩЕМУ ХОДУ</div><h2 class="player-title">История открывается за столом.</h2><p>Здесь хранятся твои записи и инструменты для игры. Добавляй то, что узнал во время встречи, и возвращайся к заметкам перед следующей.</p><div class="player-home-actions"><a class="button primary" href="#dice">Бросить кубик ↗</a><a class="button ghost" href="#notes">Сделать заметку ↗</a></div></div></section><section class="panel player-profile-summary"><div class="panel-header"><h2 class="panel-title">Мой персонаж</h2><a class="text-button" href="#character">Заполнить ↗</a></div><div class="player-profile-summary-body"><div class="player-summary-label">ИМЯ В АРХИВЕ</div><h2 class="player-summary-name">${esc(p.name)||'Пока без имени'}</h2><p class="muted">${esc(p.concept)||'Перенеси имя и характеристики из своего игрового листа.'}</p><div class="player-summary-stats">${SPECIAL.map(([k,n])=>`<div class="player-summary-stat" title="${n}"><small>${k}</small><strong>${p.special[k]}</strong></div>`).join('')}</div><p class="player-local-notice">${player.notes.length} личных заметок. Записи видны только в твоём браузере.</p></div></section></div><div class="player-tools"><a class="panel" href="#character">${icon('character')}<strong>Твой персонаж</strong><span>Характеристики, состояние и снаряжение.</span><b>↗</b></a><a class="panel" href="#notes">${icon('notes')}<strong>Твоя память</strong><span>Имена, обещания и собственные наблюдения.</span><b>↗</b></a><a class="panel" href="#dice">${icon('dice')}<strong>Твой шанс</strong><span>d4, d6, d8, d10, d12, d20 и d100.</span><b>↗</b></a></div><div class="banner"><strong>Личный архив.</strong> У каждого участника свои записи. Для переноса на другое устройство скачай копию данных в разделе «Справка».</div>`;}
function inputField(name,label,value='',type='input'){return `<div class="field"><label class="field-label" for="p-${name}">${label}</label>${type==='textarea'?`<textarea class="textarea" id="p-${name}" name="${name}" rows="4" maxlength="30000">${esc(value)}</textarea>`:`<input class="input" id="p-${name}" name="${name}" maxlength="300" value="${esc(value)}">`}</div>`;}
function character(){const p=player.profile;return head('ЛИЧНЫЙ ЛИСТ','Мой персонаж.','Удобная запись для игры. Значения определяются вашим игровым листом и правилами группы.')+`<form class="panel player-form" id="profileForm"><div class="player-form-grid">${inputField('name','ИМЯ',p.name)}${inputField('concept','РОЛЬ / КОНЦЕПЦИЯ',p.concept)}${inputField('hp','ОЖ · ТЕКУЩИЕ / МАКСИМУМ',p.hp)}${inputField('defence','ЗАЩИТА / КБ',p.defence)}</div><div class="field-label">S.P.E.C.I.A.L.</div><div class="special-grid">${SPECIAL.map(([k,name])=>`<label class="special-card" for="special-${k}"><strong>${k}</strong><span class="special-name">${name}</span><input id="special-${k}" class="input" type="number" name="special-${k}" min="1" max="10" step="1" required value="${p.special[k]}"><span class="special-mod" data-special-mod="${k}">Модификатор ${modifier(p.special[k])}</span></label>`).join('')}</div><p class="muted">Значения 5 — заготовка для заполнения. Перенеси реальные характеристики своего персонажа.</p>${inputField('inventory','ИНВЕНТАРЬ И СНАРЯЖЕНИЕ',p.inventory,'textarea')}${inputField('description','ОПИСАНИЕ И ЛИЧНЫЕ ДЕТАЛИ',p.description,'textarea')}<div class="player-form-footer"><button class="button primary" type="submit">Сохранить персонажа ↗</button><span class="player-status" id="profileStatus" role="status"></span></div></form>`;}
function notes(){return head('ТО, ЧТО ТЫ УЖЕ ЗНАЕШЬ','Мои заметки.','Записывай события, договорённости и вопросы, которые хочешь задать на следующей встрече.')+`<section class="panel player-notes-form"><form id="noteForm">${inputField('noteTitle','КОРОТКИЙ ЗАГОЛОВОК')}${inputField('noteText','ЗАПИСЬ','','textarea')}<button class="button primary" type="submit">Добавить заметку ↗</button></form></section><div class="player-note-list">${player.notes.map(n=>`<article class="panel player-note"><div class="card-top"><span class="muted">${esc(new Date(n.date).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}))}</span><div class="player-note-actions">${btn('Изменить','edit-note','ghost small',`data-id="${esc(n.id)}"`)}${btn('×','delete-note','ghost small',`data-id="${esc(n.id)}" aria-label="Удалить заметку"`)}</div></div><h2 class="card-title">${esc(n.title)||'Заметка'}</h2><p class="prewrap">${esc(n.text)}</p></article>`).join('')||'<div class="empty-state"><h3>Чистая страница.</h3><p>Первая запись появится здесь после сохранения.</p></div>'}</div>`;}
function help(){return head('ПАМЯТКА УЧАСТНИКА','Всегда под рукой.','Личные инструменты и сохранения для твоей игры.')+`<div class="player-help-grid"><section class="panel"><h2 class="card-title">Проверки</h2><p>Характеристика: <strong>1d20 + (SPECIAL − 5)</strong>.<br>Навык: <strong>1d20 + значение навыка</strong>.</p><p>Навык и характеристика одновременно не складываются. Итог сравнивается с порогом, который задаёт ведущий. Особенности и снаряжение учитывайте по правилам вашей группы.</p><p class="muted">Кубики показывают результат броска. Условия успеха определяются за столом.</p></section><section class="panel"><h2 class="card-title">Цвет и экран</h2><p>В верхней панели доступны 10 оттенков терминала. Кнопка «ЭЛТ» включает и отключает декоративные полосы экрана.</p><p>Настройки сохраняются для этого браузера.</p></section><section class="panel"><h2 class="card-title">Личные сохранения</h2><p>Персонаж и заметки хранятся на этом устройстве. Они не синхронизируются с другими участниками. История кубиков ведётся отдельно.</p><p>Очистка данных браузера удаляет локальные записи. Скачай резервную копию перед переносом на другое устройство.</p><div class="player-data-actions">${btn('↓ Скачать мои данные','backup','primary')}${btn('↥ Восстановить копию','restore','ghost')}</div></section><section class="panel"><h2 class="card-title">Без интернета</h2><p>Скачай терминал одним HTML-файлом. Для переноса персонажа и заметок также сохрани и восстанови резервную копию.</p><a href="niti-player-offline.html" download class="button ghost">↙ Скачать офлайн-версию</a></section></div>`;}
function render(){if(!pages.some(([id])=>id===view))view='home';$('#nav').innerHTML=pages.map(([id,name])=>`<a class="nav-item ${id===view?'active':''}" href="#${id}" ${id===view?'aria-current="page"':''}>${icon(id)}<span>${name}</span></a>`).join('');const name=pages.find(([id])=>id===view)[1];$('#crumb').textContent=name;document.title=name+' · Нити — игрок';$('#workspace').innerHTML=({home,character,notes,dice:dicePage,help}[view])();$('#saveStatus').textContent=storageOK?'● Личные записи в браузере':'! Не сохранено · скачай копию';}
function navigate(id){if(location.hash.slice(1)===id){view=id;render();}else location.hash=id;}
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);render();window.scrollTo(0,0);});
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download('niti-player-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(player,null,2));}
function modal(title,body,submit){lastFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div class="modal-header"><h2 id="dialogTitle">${title}</h2>${btn('×','close-modal','ghost','aria-label="Закрыть"')}</div><form id="dialogForm"><div class="modal-body">${body}</div><div class="modal-footer">${btn('Отмена','close-modal','ghost')}<button class="button primary" type="submit">Сохранить</button></div></form></section></div>`;document.body.style.overflow='hidden';$('#dialogForm').onsubmit=e=>{e.preventDefault();submit(new FormData(e.currentTarget));};$('#modalRoot button').focus();}
function closeModal(){$('#modalRoot').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
document.addEventListener('click',event=>{const b=event.target.closest('[data-player-action]');if(!b)return;const action=b.dataset.playerAction,id=b.dataset.id;if(action==='backup')backup();if(action==='restore')$('#playerBackupFile').click();if(action==='close-modal')closeModal();if(action==='edit-note'){const n=player.notes.find(n=>n.id===id);if(!n)return;modal('Изменить заметку',inputField('editTitle','ЗАГОЛОВОК',n.title)+inputField('editText','ЗАПИСЬ',n.text,'textarea'),f=>{const text=String(f.get('editText')||'').trim();if(!text){toast('Добавь текст заметки.');return;}n.title=String(f.get('editTitle')||'').trim().slice(0,200);n.text=text;save();closeModal();render();});}if(action==='delete-note')modal('Удалить заметку?','<p>Эта запись будет удалена из личного архива.</p>',()=>{player.notes=player.notes.filter(n=>n.id!==id);save();closeModal();render();});});
document.addEventListener('submit',event=>{if(event.target.id==='profileForm'){event.preventDefault();const f=new FormData(event.target),profile={...player.profile,special:{}};for(const name of ['name','concept','hp','defence','inventory','description'])profile[name]=String(f.get(name)||'').trim();for(const[k]of SPECIAL){const n=Number(f.get('special-'+k));if(!Number.isInteger(n)||n<1||n>10){toast('Характеристики должны быть целыми числами от 1 до 10.');return;}profile.special[k]=n;}player.profile=profile;const success=save();$('#profileStatus').textContent=success?'Персонаж сохранён.':'Не удалось сохранить. Скачай копию данных.';}if(event.target.id==='noteForm'){event.preventDefault();const f=new FormData(event.target),text=String(f.get('noteText')||'').trim();if(!text){toast('Добавь текст заметки.');return;}if(player.notes.length>=1000){toast('Архив заполнен. Скачай копию и удали ненужные записи.');return;}player.notes.unshift({id:uid(),title:String(f.get('noteTitle')||'').trim().slice(0,200),text,date:new Date().toISOString()});save();render();toast('Заметка добавлена.');}});
document.addEventListener('input',event=>{if(!event.target.id.startsWith('special-'))return;const key=event.target.id.slice(8),n=Number(event.target.value),label=document.querySelector('[data-special-mod="'+key+'"]');if(label)label.textContent=Number.isInteger(n)&&n>=1&&n<=10?'Модификатор '+modifier(n):'От 1 до 10';});
$('#playerBackupFile').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(!validPlayer(data))throw Error();modal('Восстановить личный архив?','<p>Персонаж и заметки будут заменены данными из выбранной копии. Текущий архив можно скачать перед восстановлением.</p>',()=>{backup();player={kind:'niti-player',version:1,profile:{...data.profile,special:{...data.profile.special}},notes:data.notes.map(n=>({id:n.id,title:n.title,text:n.text,date:n.date}))};save();closeModal();render();toast('Личный архив восстановлен.');});}catch{toast('Нужна резервная копия терминала игрока в формате JSON.');}event.target.value='';});
document.addEventListener('keydown',event=>{if(!$('#modalRoot').children.length)return;if(event.key==='Escape')closeModal();if(event.key==='Tab'){const buttons=[...$('#modalRoot').querySelectorAll('button,input,textarea,select')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
render();
